1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	// Kept as a separate additive term rather than folded into a `policyBase * 1.1`
51	// factor: that is not float-equivalent (100 * 1.1 === 110.00000000000001), and
52	// the final rounding-up turns the stray ulp into a whole extra gold piece.
53	// Do not "simplify".
54	const firstInsuranceSurcharge = (policyBase: number): number =>
55	  policyBase * FIRST_INSURANCE_RATE;
56	
57	// The MHPCO rounds premiums in its own favour: up.
58	const premiumRoundedInMHPCOsFavour = (premium: number): number =>
59	  Math.ceil(premium);
60	
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_PREMIUM = 60;
63	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
64	
65	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
66	
67	// An unenchanted item may leave `enchantment` unset; absent means level 0.
68	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
69	
70	// A group is every item of one single type, so a group is always non-empty
71	// and homogeneous — the block rule below relies on both.
72	interface TypeGroup {
73	  type: string;
74	  items: Item[];
75	}
76	
77	const groupByType = (items: Item[]): TypeGroup[] =>
78	  [
79	    ...items.reduce(
80	      (groups, item) =>
81	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
82	      new Map<string, Item[]>(),
83	    ),
84	  ].map(([type, groupedItems]) => ({ type, items: groupedItems }));
85	
86	const formsComponentBlock = (group: TypeGroup): boolean =>
87	  group.items.length === COMPONENT_BLOCK_SIZE && COMPONENT_TYPES.has(group.type);
88	
89	const sumOfItemBasePremiums = (items: Item[]): number =>
90	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
91	
92	const groupBasePremium = (group: TypeGroup): number =>
93	  formsComponentBlock(group)
94	    ? COMPONENT_BLOCK_PREMIUM
95	    : sumOfItemBasePremiums(group.items);
96	
97	const policyBasePremium = (items: Item[]): number =>
98	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
99	
100	const CURSE_SURCHARGE_RATE = 0.5;
101	
102	// Item-specific modifiers are charged on the affected item's own base premium,
103	// unlike the policy-wide modifiers which apply to the sum of all of them.
104	const curseSurcharge = (item: Item): number =>
105	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
106	
107	// The surcharge threshold below and the reimbursement threshold further down
108	// are two unrelated rules that happen to share the word "enchantment". They
109	// are named apart on purpose: neither is the general case of the other, and
110	// they are deliberately not the same number.
111	const SURCHARGE_ENCHANTMENT_LEVEL = 5;
112	const SURCHARGE_ENCHANTMENT_RATE = 0.3;
113	
114	const isEnchantedEnoughToSurcharge = (item: Item): boolean =>
115	  enchantmentLevelOf(item) >= SURCHARGE_ENCHANTMENT_LEVEL;
116	
117	const enchantmentSurcharge = (item: Item): number =>
118	  isEnchantedEnoughToSurcharge(item)
119	    ? basePremiumOf(item) * SURCHARGE_ENCHANTMENT_RATE
120	    : 0;
121	
122	const itemSurcharge = (item: Item): number =>
123	  curseSurcharge(item) + enchantmentSurcharge(item);
124	
125	const totalItemSurcharges = (items: Item[]): number =>
126	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
127	
128	const LOYALTY_YEARS = 2;
129	const LOYALTY_DISCOUNT_RATE = 0.2;
130	
131	const loyaltyDiscount = (customer: Customer, policyBase: number): number =>
132	  customer.yearsWithMHPCO >= LOYALTY_YEARS
133	    ? policyBase * LOYALTY_DISCOUNT_RATE
134	    : 0;
135	
136	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
137	
138	// Every contract after the customer's first is a follow-up. Which contract
139	// this is depends on how many quotes preceded it in the scenario, not on the
140	// customer record.
141	const followUpDiscount = (precedingQuotes: number, policyBase: number): number =>
142	  precedingQuotes > 0 ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
143	
144	// Everything a step needs beyond its own payload: who is buying, where in the
145	// scenario the step sits, and the surrounding steps a claim resolves its
146	// `policy` reference against. Bundled so callers thread one named value rather
147	// than a trail of bare parameters.
148	interface StepContext {
149	  customer: Customer;
150	  precedingQuotes: number;
151	  steps: Step[];
152	  // Cap left on each policy that has already been claimed against; a policy
153	  // absent from the map has its full cap available.
154	  remainingCapByPolicy: Map<number, number>;
155	}
156	
157	// Policy-wide modifiers are charged on the sum of all item base premiums,
158	// unlike the item-specific ones above. Each returns a signed adjustment:
159	// surcharges positive, discounts negative.
160	const policyModifiers = (policyBase: number, context: StepContext): number =>
161	  firstInsuranceSurcharge(policyBase) -
162	  loyaltyDiscount(context.customer, policyBase) -
163	  followUpDiscount(context.precedingQuotes, policyBase);
164	
165	const quotePremium = (items: Item[], context: StepContext): number => {
166	  const policyBase = policyBasePremium(items);
167	  return premiumRoundedInMHPCOsFavour(
168	    policyBase +
169	      policyModifiers(policyBase, context) +
170	      totalItemSurcharges(items) +
171	      PROCESSING_FEE,
172	  );
173	};
174	
175	const DEDUCTIBLE = 100;
176	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
177	  sword: 1000,
178	  amulet: 600,
179	  staff: 800,
180	  potion: 400,
181	  rune: 250,
182	  moonstone: 250,
183	};
184	const CAP_MULTIPLE = 2;
185	
186	// And payouts in its own favour too: down.
187	const payoutRoundedInMHPCOsFavour = (payout: number): number =>
188	  Math.floor(payout);
189	
190	const insuranceSum = (items: Item[]): number =>
191	  items.reduce((sum, item) => sum + INSURANCE_VALUE_BY_TYPE[item.type], 0);
192	
193	const capOf = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLE;
194	
195	// Unrelated to the surcharge threshold above — see the note there.
196	const HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
197	const HALVED_REIMBURSEMENT_RATE = 0.5;
198	
199	// Highly enchanted items are notoriously hard to appraise, so the MHPCO
200	// reimburses only half their damage.
201	const isEnchantedEnoughToHalve = (item: Item): boolean =>
202	  enchantmentLevelOf(item) >= HALVED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
203	
204	const coveredAmount = (damage: Damage, item: Item): number =>
205	  isEnchantedEnoughToHalve(item)
206	    ? damage.amount * HALVED_REIMBURSEMENT_RATE
207	    : damage.amount;
208	
209	const reimbursement = (damage: Damage, item: Item): number =>
210	  coveredAmount(damage, item) - DEDUCTIBLE;
211	
212	const damagedItem = (insuredItems: Item[], damage: Damage): Item => {
213	  const item = insuredItems.find(({ type }) => type === damage.itemType);
214	  if (item === undefined) {
215	    throw new Error(`${damage.itemType} is not insured by this policy`);
216	  }
217	  return item;
218	};
219	
220	const claimPayout = (incident: Incident, insuredItems: Item[]): number =>
221	  payoutRoundedInMHPCOsFavour(
222	    incident.damages.reduce(
223	      (total, damage) =>
224	        total + reimbursement(damage, damagedItem(insuredItems, damage)),
225	      0,
226	    ),
227	  );
228	
229	const insuredItemsOf = (steps: Step[], policy: number): Item[] => {
230	  const policyStep = steps[policy];
231	  if (policyStep.op !== "quote") {
232	    throw new Error(`step ${policy} is not a quote`);
233	  }
234	  return policyStep.items;
235	};
236	
237	const runStep = (step: Step, context: StepContext): StepResult => {
238	  if (step.op === "quote") {
239	    return { premium: quotePremium(step.items, context) };
240	  }
241	  const insuredItems = insuredItemsOf(context.steps, step.policy);
242	  const availableCap = context.remainingCapByPolicy.get(step.policy) ?? capOf(insuredItems);
243	  const payout = Math.min(claimPayout(step.incident, insuredItems), availableCap);
244	  return { payout, remainingCap: availableCap - payout };
245	};
246	
247	export const runScenario = (scenario: Scenario): ScenarioResult => {
248	  const remainingCapByPolicy = new Map<number, number>();
249	  let precedingQuotes = 0;
250	  const results = scenario.steps.map((step) => {
251	    const result = runStep(step, {
252	      customer: scenario.customer,
253	      precedingQuotes,
254	      steps: scenario.steps,
255	      remainingCapByPolicy,
256	    });
257	    if (step.op === "quote") {
258	      precedingQuotes += 1;
259	    } else {
260	      remainingCapByPolicy.set(step.policy, (result as { remainingCap: number }).remainingCap);
261	    }
262	    return result;
263	  });
264	  return { results };
265	};
