const runStep = (step: Step, context: StepContext): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, context) };
  }
  const insuredItems = insuredItemsOf(context.steps, step.policy);
  const availableCap = context.remainingCapByPolicy.get(step.policy) ?? capOf(insuredItems);
  const payout = Math.min(claimPayout(step.incident, insuredItems), availableCap);
  return { payout, remainingCap: availableCap - payout };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const remainingCapByPolicy = new Map<number, number>();
  let precedingQuotes = 0;
  const results = scenario.steps.map((step) => {
    const result = runStep(step, {
      customer: scenario.customer,
      precedingQuotes,
      steps: scenario.steps,
      remainingCapByPolicy,
    });
    if (step.op === "quote") {
      precedingQuotes += 1;
    } else {
      remainingCapByPolicy.set(step.policy, (result as { remainingCap: number }).remainingCap);
    }
    return result;
  });
  return { results };
};

